    'Erase again, and then',
    'A poppy blooms.'
  ]
};

export default function Poem() {
  let output = [];

  // Output dizisine ekleyin
  poem.lines.forEach((line, i) => {
    output.push(
      <hr key={i + '-separator'} />
    );
    output.push(
      <p key={i + '-text'}>
        {line}
      </p>
    );
  });
  // İlk <hr /> elementi silin
  output.shift();

  return (
    <article>
      {output}
    </article>
  );
}

