function TestCase({
  baseState,
  queue,
  expected
}) {
  const actual = getFinalState(baseState, queue);
  return (
    <>
      <p>Başlangıç state'i: <b>{baseState}</b></p>
      <p>Kuyruk: <b>[{queue.join(', ')}]</b></p>
      <p>Beklenen sonuç: <b>{expected}</b></p>
      <p style={{
        color: actual === expected ?
          'green' :
          'red'
      }}>
        Sonucunuz: <b>{actual}</b>
        {' '}
        ({actual === expected ?
          'correct' :
          'wrong'
        })
      </p>
    </>
  );
}

