    // Daha önceden seçili miydi?
    if (selectedIds.includes(toggledId)) {
      // Öyleyse bu ID'yi diziden kaldır.
      setSelectedIds(selectedIds.filter(id =>
        id !== toggledId
      ));
    } else {
      // Aksi halde diziye ekle.
      setSelectedIds([
        ...selectedIds,
        toggledId
      ]);
